<?php
require dirname(__DIR__).'/bootstrap.php';
try{post_only();verify_csrf();$p=json_decode(file_get_contents('php://input'),true);if(!is_array($p))throw new InvalidArgumentException('Données invalides');
 $pickup=clean((string)($p['pickup']??''));$dropoff=clean((string)($p['dropoff']??''));$first=clean((string)($p['first_name']??''),120);$last=clean((string)($p['last_name']??''),120);$phone=clean((string)($p['phone']??''),40);$email=clean((string)($p['email']??''),190);if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new InvalidArgumentException('Adresse e-mail invalide');$address=clean((string)($p['address']??''));
 $coords=[];foreach(['pickup_lat','pickup_lng','dropoff_lat','dropoff_lng'] as $k){$v=$p[$k]??null;if(!is_numeric($v))throw new InvalidArgumentException('Veuillez sélectionner les adresses Google');$coords[$k]=(float)$v;}if(abs($coords['pickup_lat'])>90||abs($coords['dropoff_lat'])>90||abs($coords['pickup_lng'])>180||abs($coords['dropoff_lng'])>180)throw new InvalidArgumentException('Coordonnées incorrectes');
 $when=(string)($p['when']??'');$d=DateTimeImmutable::createFromFormat('!Y-m-d\TH:i',$when,new DateTimeZone('Europe/Paris'));if(!$d||$d<new DateTimeImmutable('now',new DateTimeZone('Europe/Paris')))throw new InvalidArgumentException('Veuillez choisir une heure future');
 $route=google_route($coords['pickup_lat'],$coords['pickup_lng'],$coords['dropoff_lat'],$coords['dropoff_lng'],$when);$price=calculate_price($route,$dropoff,$when);$utc=$d->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s');$db=db();$db->beginTransaction();
 $s=$db->prepare('INSERT INTO islem_customers(first_name,last_name,email,phone,address) VALUES (?,?,?,?,?)');$s->execute([$first,$last,$email,$phone,$address]);$customer=(int)$db->lastInsertId();$code=booking_code();
 $s=$db->prepare('INSERT INTO islem_bookings(booking_code,customer_id,pickup_address,pickup_lat,pickup_lng,dropoff_address,dropoff_lat,dropoff_lng,pickup_at,customer_address,quoted_total,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$s->execute([$code,$customer,$pickup,$coords['pickup_lat'],$coords['pickup_lng'],$dropoff,$coords['dropoff_lat'],$coords['dropoff_lng'],$utc,$address,$price['total'],'pending']);$id=(int)$db->lastInsertId();
 $s=$db->prepare('INSERT INTO islem_quotes(booking_id,distance_m,duration_seconds,duration_traffic_seconds,distance_amount,traffic_amount,scheduled_amount,other_amount,total,detail_json) VALUES(?,?,?,?,?,?,?,?,?,?)');$s->execute([$id,$route['distance'],$route['duration'],$route['traffic'],$price['distance'],$price['traffic'],$price['rush'],$price['extra'],$price['total'],json_encode($price)]);
 $token=bin2hex(random_bytes(32));$s=$db->prepare('INSERT INTO islem_customer_access (booking_id,token_hash,expires_at) VALUES (?,?,DATE_ADD(UTC_TIMESTAMP(),INTERVAL 30 DAY))');$s->execute([$id,hash('sha256',$token)]);$db->commit();json_reply(['ok'=>true,'code'=>$code,'total'=>$price['total'],'track'=>'/suivi.php?token='.$token]);
}catch(Throwable $ex){if(isset($db)&&$db->inTransaction())$db->rollBack();json_reply(['error'=>$ex->getMessage()],422);}
